insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values
('b2economy-grammar','Sprzedaż wzrosła ___ dwanaście procent.','["o","z","na"]',0,'Wzrosła o отвечает на вопрос, на сколько изменился показатель.',0),
('b2economy-grammar','Udział zakupów online zwiększył się ___ 28% do 35%.','["z","o","przez"]',0,'Z… do… показывает начальное и конечное значение.',1),
('b2economy-grammar','W tym roku wydatki były nieco mniejsze ___ rok wcześniej.','["niż","od","jak"]',0,'Сравнительная степень с конкретным показателем соединяется через niż.',2),
('b2economy-grammar','Według prognozy ceny ___ ustabilizują się jesienią.','["prawdopodobnie","na pewno już","bez wątpienia wczoraj"]',0,'Prawdopodobnie маркирует прогноз, а не установленный факт.',3),
('b2economy-grammar','Составьте: Спрос вырос на 8%, но предложение почти не изменилось.','["Popyt wzrósł o 8%, ale podaż prawie się nie zmieniła.","Popyt wzrósł z 8%, lecz podaż zmienił się prawie.","Podaż o popyt osiem wzrosła bez zmiany."]',0,'Изменение на величину выражается wzrósł o, а podaż требует формы zmieniła.',4),
('b2economy-grammar','Составьте: Вероятно, этот вариант будет выгоднее по сравнению с предыдущим.','["Prawdopodobnie ten wariant będzie bardziej opłacalny w porównaniu z poprzednim.","Ten wariant na pewno opłacalny od poprzedni prawdopodobieństwo.","W porównaniu poprzednim wariant będzie opłacalność."]',0,'Прогноз вводит prawdopodobnie, сравнение — w porównaniu z + творительный.',5),
('b2economy-quiz','Co oznacza siła nabywcza?','["ilość dóbr, które można kupić za dochód","liczbę sklepów","wysokość podaży jednego produktu"]',0,'Покупательная способность показывает, сколько благ позволяет приобрести доход.',0),
('b2economy-quiz','Ceny spadły z 120 do 108 zł. O ile procent w przybliżeniu?','["o 10%","o 12%","do 10%"]',0,'Разница 12 от исходных 120 составляет 10%.',1),
('b2economy-quiz','Które słowo nazywa zapotrzebowanie klientów?','["popyt","podaż","udział"]',0,'Popyt — спрос покупателей; podaż — предложение продавцов.',2),
('b2economy-quiz','Dochód wzrósł ___ 5%.','["o","z","do"]',0,'O 5% обозначает величину роста.',3),
('b2economy-quiz','Co sygnalizuje ostrożny wniosek?','["Możliwe, że tendencja się utrzyma.","Tendencja na pewno trwa od zawsze.","Nie trzeba sprawdzać danych."]',0,'Możliwe, że отмечает возможность, а не уверенность.',4),
('b2economy-quiz','Który wariant jest najbardziej opłacalny?','["Ten o najniższym łącznym koszcie i odpowiedniej jakości","Zawsze ten z najniższą ceną początkową","Ten bez warunków umowy"]',0,'Выгодность учитывает все расходы и качество, не только ценник.',5),
('b2economy-quiz','Udział wzrósł z 20% do 30%, czyli o ___.','["10 punktów procentowych","10 procent wartości","50 punktów"]',0,'Разница долей равна 10 процентным пунктам.',6),
('b2economy-quiz','Dane wahały się, czyli ___.','["zmieniały się w górę i w dół","stale rosły","pozostały identyczne"]',0,'Wahać się — колебаться между значениями.',7),
('b2economy-quiz','Co należy zrobić przed decyzją konsumencką?','["porównać całkowite koszty i warunki","opierać się wyłącznie na reklamie","pominąć ryzyko"]',0,'Сопоставление условий делает решение обоснованным.',8),
('b2economy-quiz','Które zdanie opisuje prognozę?','["Popyt prawdopodobnie wzrośnie w kolejnym kwartale.","Popyt wzrósł wczoraj o 4%.","Raport podaje wynik za maj."]',0,'Будущее и маркер вероятности создают прогноз.',9),
('b2economy-reading-check','O ile punktów procentowych wzrósł udział subskrypcji?','["O pięć","O czternaście","O dziewięć"]',0,'Доля изменилась с 9% до 14%, то есть на 5 п.п.',0),
('b2economy-reading-check','Co obejmuje abonament poza urządzeniem?','["Naprawy","Zakup mieszkania","Dowolną wymianę bez warunków"]',0,'В тексте прямо упомянут включённый ремонт.',1),
('b2economy-reading-check','Ile może wynieść suma opłat po czterech latach?','["3900 zł","1800 zł","2100 zł"]',0,'Максимальная указанная сумма — 3900 zł.',2),
('b2economy-reading-check','Dlaczego firmy rozwijają subskrypcje?','["Szukają stałych przychodów","Maleje cała podaż","Zakazano sprzedaży"]',0,'Регулярная выручка названа причиной прогноза.',3),
('b2economy-reading-check','Jakie ryzyko wskazuje tekst?','["Podwyżkę opłat lub karę za wcześniejsze rozwiązanie","Brak jakichkolwiek kosztów","Gwarantowany spadek cen"]',0,'Оба риска перечислены в четвёртом абзаце.',4),
('b2economy-reading-check','Co jest podstawą rozsądnej decyzji?','["Porównanie pełnych kosztów, warunków i potrzeb","Tylko wysokość raty","Slogan reklamowy"]',0,'Финальный вывод требует анализа нескольких факторов.',5);
insert into public.reading_texts(id,topic_id,title,description,level,minutes,emoji,paragraphs,glossary,source_metadata,position,is_active) values ('b2economy-subskrypcja-czy-zakup','b2-economy-consumption','Subskrypcja czy zakup? Decyzja oparta na danych','Как числа, скрытые расходы и степень уверенности меняют потребительский выбор','B2',12,'📊','["Coraz więcej osób korzysta ze sprzętu domowego w modelu subskrypcyjnym zamiast kupować go na własność. Z raportu miejskiego rzecznika konsumentów wynika, że udział takich umów wzrósł w ciągu dwóch lat z 9% do 14%. To wzrost o pięć punktów procentowych, a nie o pięć procent. Popyt zwiększył się przede wszystkim wśród osób, które często zmieniają miejsce zamieszkania.","Miesięczna opłata wydaje się niska, jednak o opłacalności decyduje łączny koszt. Przy umowie na trzy lata klient może zapłacić ponad dwa razy więcej niż wynosi cena urządzenia. Z drugiej strony abonament obejmuje naprawy, a więc zmniejsza ryzyko nieprzewidzianych wydatków. Korzyść zależy zatem od czasu użytkowania i warunków serwisu.","Analitycy porównali trzy oferty pralek. Cena zakupu wahała się od 1800 do 2400 złotych, natomiast suma opłat abonamentowych wynosiła od 2100 zł po dwóch latach do 3900 zł po czterech. Dochody badanych gospodarstw były podobne, lecz ich priorytety się różniły: jedni cenili przewidywalne wydatki, inni chcieli zachować pełną własność.","Prognoza zakłada, że podaż usług subskrypcyjnych prawdopodobnie wzrośnie, ponieważ firmy szukają stałych przychodów. Nie oznacza to jednak, że taki model zawsze będzie korzystny. Istnieje ryzyko podwyżki opłat, kary za wcześniejsze rozwiązanie umowy oraz ograniczonego wyboru serwisu.","Rozsądna decyzja wymaga więc porównania danych, całkowitego kosztu i własnych potrzeb. Konsument powinien odróżnić potwierdzony wynik od przewidywania, sprawdzić okres umowy i policzyć kilka scenariuszy. Dopiero wtedy niska rata może zostać oceniona jako rzeczywista oszczędność, a nie tylko atrakcyjny komunikat reklamowy."]','{"subskrypcyjnym":{"lemma":"subskrypcyjny","translation":"подписочный","part_of_speech":"прилагательное"},"na własność":{"lemma":"na własność","translation":"в собственность","part_of_speech":"устойчивое выражение"},"udział":{"lemma":"udział","translation":"доля","part_of_speech":"существительное"},"rzecznika":{"lemma":"rzecznik","translation":"уполномоченный, представитель","part_of_speech":"существительное"},"punktów procentowych":{"lemma":"punkt procentowy","translation":"процентных пунктов","part_of_speech":"словосочетание"},"łączny":{"lemma":"łączny","translation":"совокупный","part_of_speech":"прилагательное"},"opłacalności":{"lemma":"opłacalność","translation":"выгодность","part_of_speech":"существительное"},"abonament":{"lemma":"abonament","translation":"абонентская плата","part_of_speech":"существительное"},"nieprzewidzianych":{"lemma":"nieprzewidziany","translation":"непредвиденных","part_of_speech":"прилагательное"},"użytkowania":{"lemma":"użytkowanie","translation":"использование","part_of_speech":"существительное"},"wahała się":{"lemma":"wahać się","translation":"колебалась","part_of_speech":"глагол"},"przewidywalne":{"lemma":"przewidywalny","translation":"предсказуемые","part_of_speech":"прилагательное"},"podaż":{"lemma":"podaż","translation":"предложение","part_of_speech":"существительное"},"przychodów":{"lemma":"przychód","translation":"выручка, доход","part_of_speech":"существительное"},"podwyżki":{"lemma":"podwyżka","translation":"повышение","part_of_speech":"существительное"},"rozwiązanie umowy":{"lemma":"rozwiązanie umowy","translation":"расторжение договора","part_of_speech":"словосочетание"},"scenariuszy":{"lemma":"scenariusz","translation":"сценариев","part_of_speech":"существительное"},"rata":{"lemma":"rata","translation":"платёж, взнос","part_of_speech":"существительное"},"oszczędność":{"lemma":"oszczędność","translation":"экономия","part_of_speech":"существительное"},"przewidywania":{"lemma":"przewidywanie","translation":"прогноз, предположение","part_of_speech":"существительное"}}','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30","comprehension_lesson_id":"b2economy-reading-check"}',40,true) on conflict(id) do update set topic_id=excluded.topic_id,title=excluded.title,description=excluded.description,level=excluded.level,minutes=excluded.minutes,emoji=excluded.emoji,paragraphs=excluded.paragraphs,glossary=excluded.glossary,source_metadata=excluded.source_metadata,position=excluded.position,is_active=excluded.is_active;
